mapper.select:
SELECT ${dimensionColumn} AS dim_value, COUNT(*) AS cnt
FROM biz_call_record


        AND biz_type = #{bizType}


        AND gmt_create >= #{startDate}


        AND gmt_create < DATE_ADD(#{endDate}, INTERVAL 1 DAY)


GROUP BY ${dimensionColumn}
ORDER BY cnt DESC

SELECT ${dimensionColumn} AS dim_value, DATE_FORMAT(gmt_create, '%Y-%m-%d') AS call_date, COUNT(*) AS cnt FROM biz_call_record
AND biz_type = #{bizType}
AND gmt_create >= #{startDate}
AND gmt_create < DATE_ADD(#{endDate}, INTERVAL 1 DAY)
GROUP BY ${dimensionColumn}, call_date ORDER BY call_date ASC

SELECT COUNT(*) FROM biz_call_record


        AND biz_type = #{bizType}


        AND gmt_create >= #{startDate}


        AND gmt_create < DATE_ADD(#{endDate}, INTERVAL 1 DAY)
